def free_compose_acquired_disclosures(source_output, statements):
    if not isinstance(source_output, dict):
        return
    for row in source_output.get('statements', []):
        if not isinstance(row, dict):
            continue
        term = row.get('term')
        if not isinstance(term, list) or len(term) != 11 or term[0] != 'acq_disclosure_v3':
            continue
        effect = term[2]
        actor_name = term[3]
        role = term[4]
        owner_name = term[5]
        if effect not in ('operative_permission', 'class_permission'):
            continue
        if owner_name == 'receiving_party':
            owner = ['receiving_party']
        elif owner_name == 'controlled_entity':
            owner = ['controlled_entities_of', ['receiving_party']]
        else:
            continue
        if role == 'employee':
            recipient = ['employees_of', owner]
        elif role == 'contractor':
            recipient = ['independent_contractors_of', owner]
        elif role == 'consultant':
            recipient = ['consultants_of', owner]
        elif role == 'agent':
            recipient = ['agents_of', owner]
        elif role == 'professional_adviser':
            recipient = ['professional_advisors_of', owner]
        elif role == 'representative':
            recipient = ['representatives_of', owner]
        else:
            continue
        actor = ['receiving_party'] if actor_name == 'receiving_party' else ['named_recipient', actor_name]
        raw = term[10]
        conditions = []
        if term[6] == 'required':
            conditions.append(['need_to_know', raw])
        if term[7] == 'required':
            conditions.append(['extent_necessary', raw])
        if term[8] in ('required', 'written_required'):
            conditions.append(['confidentiality_bound', raw])
        norm = ['permission', actor, ['disclose', ['confidential_information'], recipient], make_and(conditions)]
        add_statement(statements, norm, row.get('support_ids', []))
def apply(inputs, premises):
    source_output = inputs.get('source_output', {})
    statements = []
    unresolved = []
    complete = False
    if isinstance(source_output, dict):
        complete = bool(source_output.get('complete', False))
        for row in source_output.get('statements', []):
            if isinstance(row, dict) and isinstance(row.get('term'), list):
                statements.append({'term': row.get('term'), 'support_ids': list(row.get('support_ids', []))})
        for item in source_output.get('unresolved', []):
            if isinstance(item, str) and item not in unresolved:
                unresolved.append(item)
    free_compose_acquired_disclosures(source_output, statements)
    spans = []
    all_ids = []
    elliptical = False
    for span in inputs.get('source_spans', []):
        if isinstance(span, dict):
            spans.append(span)
            all_ids.append(span.get('id'))
    for span in spans:
        uid = span.get('id')
        raw = span.get('text', '')
        if not isinstance(raw, str):
            raw = str(raw)
        if free_elliptical_permission(raw, uid, statements):
            elliptical = True
        free_add_disposal_repairs(raw, uid, statements)
    if not free_disposal_present(spans):
        add_statement(statements, ['complete_source_no_disposal_obligation'], all_ids)
    if not free_post_disposal_retention_present(spans):
        add_statement(statements, ['complete_source_no_retention_effect'], all_ids)
    if not free_internal_permission_present(spans) and not elliptical:
        add_statement(statements, ['complete_source_no_disclosure_permission'], all_ids)
    return {'statements': statements, 'complete': complete and len(unique(unresolved)) == 0, 'unresolved': unique(unresolved)}

